        ('calcium_mg', 'Кальций', 'мг', 1000, 'RDA', 'minimum', 'https://ods.od.nih.gov/factsheets/Calcium-HealthProfessional/', 'Ориентир для взрослого 19–50 лет.', 4),
        ('iron_mg', 'Железо', 'мг', 8, 'RDA', 'minimum', 'https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/', 'Ориентир для мужчины 19–50 лет.', 5),
        ('vitamin_c_mg', 'Витамин C', 'мг', 90, 'RDA', 'minimum', 'https://ods.od.nih.gov/factsheets/VitaminC-HealthProfessional/', 'Ориентир для взрослого мужчины.', 6),
        ('vitamin_d_mcg', 'Витамин D', 'мкг', 15, 'RDA', 'minimum', 'https://ods.od.nih.gov/factsheets/VitaminD-HealthProfessional/', 'Пищевой ориентир для взрослого 19–70 лет.', 7),
