INSERT INTO nutrition_components (
    nutrition_entry_id, component_name, estimated_weight_g,
    reference_fdc_id, confidence, notes
)
SELECT
    n.id,
    c.component_name,
    c.estimated_weight_g,
    c.reference_fdc_id,
    c.confidence,
    c.notes
FROM component_data AS c
JOIN calendar_days AS d ON d.diary_date = c.diary_date
JOIN nutrition_entries AS n
  ON n.calendar_day_id = d.id
 AND n.meal_type = c.meal_type
 AND n.food_name = c.entry_food_name
WHERE 1
ON CONFLICT (nutrition_entry_id, component_name) DO UPDATE SET
    estimated_weight_g = excluded.estimated_weight_g,
    reference_fdc_id = excluded.reference_fdc_id,
    confidence = excluded.confidence,
    notes = excluded.notes;

